      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Long root notes with gentle decay",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Root-fifth motion with light passing tones",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "More active walking bass connecting chord changes",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "Adds occasional upper octave and fills in gaps",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Sustained notes, sometimes pedal on B, with slow stepwise movement",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Driving but smooth root-based line with syncopation",
          "density": "dense"
        }
      ]
    },
    {
      "id": "brush_drums",
      "name": "Brush Percussion",
      "role": "Pulse / Percussion",
