        "low": 35,
        "high": 81
      },
      "instrument_hint": "brush kit (soft kick, snare with brushes, hi-hat, ride)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Only soft hi-hat on offbeats, barely present",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Brush snare on 2 and 4, light hi-hat eighths",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "Adds cross-stick and ride pattern, slightly more energy",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Similar to verse1 but with more ride instead of hi-hat",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Drops to shaker-like hi-hat and subtle cymbal swells",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Full brush pattern with snare on 2/4, ride, and occasional tom fills",
          "density": "dense"
        }
      ]
    },
    {
      "id": "cello",
      "name": "Cello",
      "role": "Sustained texture / countermelody",
      "register": {
        "low": 36,
        "high": 72
      },
      "instrument_hint": "cello (warm sustained lines and short motifs)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Long sustained tonic or fifth above guitar",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Short answering phrases, filling gaps after vocal (or implied vocal)",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "More present countermelody, harmonizing with main line",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Takes a more lead-like role, weaving around the guitar",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Main melodic voice in B minor, expressive but restrained",
          "density": "dense"
        },
        {
          "section_id": "final_chorus",
          "intent": "High sustained notes and countermelody, adding emotional lift",
          "density": "dense"
        }
      ]
    },
    {
      "id": "counterline",
      "name": "Subtle Counterline",
      "role": "Subtle melodic echo",
      "register": {
        "low": 55,
        "high": 84
      },
      "instrument_hint": "violin or soft synth lead (gentle, breathy)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Tacet, enters later",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Occasional single-note echoes, filling space after phrases",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "More active, harmonizing with cello and guitar",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Alternates with cello, taking turns for melodic fills",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Harmonizes with cello, sometimes in thirds",
          "density": "medium"
        },
        {
          "section_id": "final_chorus",
          "intent": "Adds a high obligato line, sparse but bright",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "warm_keys",
      "name": "Warm Keys",
      "role": "Harmonic pad / sparse chords",
      "register": {
        "low": 48,
        "high": 76
      },
      "instrument_hint": "warm electric piano or soft organ",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Soft sustained chord, very quiet",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Sparse chord stabs on offbeats or long tones",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "Adds fuller sustained chords, supporting guitar",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Simpler, only sustaining root notes, leaving room",
          "density": "sparse"
        },
        {
          "section_id": "bridge",
          "intent": "Tacet or extremely subtle pad in B minor",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Adds a new sustained chord color, maybe with added 9th",
          "density": "medium"
        }
      ]
    }
  ],
  "motif_strategy": "Main motif is a four-note rising phrase first heard in intro guitar, later echoed by cello and counterline; bridge develops it in minor, final chorus extends it with a leap.",
  "harmony_strategy": "Diatonic I-V-vi-IV progressions with occasional ii; bridge moves to relative minor (B minor) with iv-VII-III-VI; final chorus returns to D with added color tones (sus2, add9).",
  "groove_strategy": "Brush percussion evolves from offbeat hi-hat to full brush pattern; bass and guitar interlock with eighth-note syncopation in chorus, while verses stay more straight-ahead; bridge uses rubato feel with minimal percussive pulse."
}

EXPERIMENTAL MUSIC SPEC SCHEMA:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://auto-studio.local/q0/experimental-music-spec.schema.json",
  "title": "ExperimentalMusicSpec",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "tempo_map", "key_map", "sections", "tracks"],
  "properties": {
    "title": {"type": "string", "minLength": 1, "maxLength": 120},
    "tempo_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/tempo_change"}},
    "key_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/key_change"}},
    "sections": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/section"}},
    "tracks": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "#/$defs/track"}}
  },
  "$defs": {
    "time_signature": {
      "type": "object", "additionalProperties": false,
      "required": ["numerator", "denominator"],
      "properties": {
        "numerator": {"type": "integer", "minimum": 1, "maximum": 32},
        "denominator": {"enum": [1, 2, 4, 8, 16, 32]}
      }
    },
    "tempo_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "bpm", "time_signature"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "bpm": {"type": "number", "minimum": 30, "maximum": 300},
        "time_signature": {"$ref": "#/$defs/time_signature"}
      }
    },
    "key_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "tonic", "mode"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "tonic": {"type": "string", "minLength": 1, "maxLength": 8},
        "mode": {"type": "string", "minLength": 1, "maxLength": 32}
      }
    },
    "section": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "label", "start_bar", "length_bars", "intent"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "label": {"type": "string", "minLength": 1, "maxLength": 80},
        "start_bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "length_bars": {"type": "integer", "minimum": 1, "maximum": 128},
        "intent": {"type": "string", "minLength": 1, "maxLength": 240}
      }
    },
    "register": {
      "type": "object", "additionalProperties": false,
      "required": ["low", "high"],
      "properties": {
        "low": {"type": "integer", "minimum": 0, "maximum": 127},
        "high": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "note": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "duration", "pitch", "velocity"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "duration": {"type": "number", "exclusiveMinimum": 0},
        "pitch": {"type": "integer", "minimum": 0, "maximum": 127},
        "velocity": {"type": "integer", "minimum": 1, "maximum": 127}
      }
    },
    "cc": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "controller", "value"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "controller": {"type": "integer", "minimum": 0, "maximum": 127},
        "value": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "region": {
      "type": "object", "additionalProperties": false,
      "required": ["section_id", "notes", "cc"],
      "properties": {
        "section_id": {"type": "string", "minLength": 1, "maxLength": 48},
        "notes": {"type": "array", "maxItems": 2048, "items": {"$ref": "#/$defs/note"}},
        "cc": {"type": "array", "maxItems": 1024, "items": {"$ref": "#/$defs/cc"}}
      }
    },
    "track": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "name", "role", "register", "instrument_hint", "regions"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "name": {"type": "string", "minLength": 1, "maxLength": 80},
        "role": {"type": "string", "minLength": 1, "maxLength": 80},
        "register": {"$ref": "#/$defs/register"},
        "instrument_hint": {"type": "string", "minLength": 1, "maxLength": 120},
        "regions": {"type": "array", "maxItems": 48, "items": {"$ref": "#/$defs/region"}}
      }
    }
  }
}
